def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Improved version of `equation_v2`."""
    """Improved version of `equation_v2`, with quadratic and exponential term."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * gate_voltage_abs ** 2 + parameters[3] * np.exp(parameters[4] * gate_voltage_abs)
